mapper.select:
SELECT u.id, u.user_no, u.name, u.phone, u.college_id, u.class_id, u.status, u.must_change_password, u.first_login_verified, (u.openid IS NOT NULL AND u.openid != '') AS openidBound, u.lock_until, u.created_at, c.name AS collegeName, sc.name AS className FROM sys_user u LEFT JOIN college c ON c.id = u.college_id AND c.deleted = 0 LEFT JOIN school_class sc ON sc.id = u.class_id AND sc.deleted = 0 WHERE u.deleted = 0 AND u.college_id = #{collegeId} AND u.status = #{status}
AND (u.user_no LIKE CONCAT(#{keyword}, '%') ESCAPE '|' OR u.name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '|')
AND EXISTS (SELECT 1 FROM sys_user_role ur JOIN sys_role r ON r.id = ur.role_id WHERE ur.user_id = u.id AND ur.deleted = 0 AND r.deleted = 0 AND r.role_code = #{roleCode})
ORDER BY u.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1) FROM sys_user u WHERE u.deleted = 0 AND u.college_id = #{collegeId} AND u.status = #{status}
AND (u.user_no LIKE CONCAT(#{keyword}, '%') ESCAPE '|' OR u.name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '|')
AND EXISTS (SELECT 1 FROM sys_user_role ur JOIN sys_role r ON r.id = ur.role_id WHERE ur.user_id = u.id AND ur.deleted = 0 AND r.deleted = 0 AND r.role_code = #{roleCode})
